const body = $json.body ?? $json ?? {};
const claims = $json.jwtPayload ?? {};
const userId = claims.sub || body.user_id || '00000000-0000-4000-8000-000000000000';
const prompt = String(body.message || body.business || '').trim() || 'Hello';
const messages = Array.isArray(body.messages) ? body.messages.slice(-30) : [];
return [{
  json: {
    session_id: body.session_id || '00000000-0000-4000-8000-000000000000',
    user_id: userId,
    message: prompt,
    messages,
    blueprint: body.blueprint && typeof body.blueprint === 'object' ? body.blueprint : null,
    asset_context: String(body.asset_context || ''),
    workspace_context: String(body.workspace_context || body.asset_context || '')
  }
}];

